from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")

old_capture = """- 鹵獲：対戦車砲装甲車両は有人車両として扱う。生命点が1のときにCore v1.01の【ネゴシエーション】に成功した場合、乗員を【捕虜】にし、車両を【鹵獲】して戦闘から除外する。この場合、車両を撃破したわけではないため民兵は潰走せず、残存民兵との戦闘を継続する。ここは最終イベントであるため、Core v1.01の【車両】鹵獲によるd66一の位補正を使用する機会は発生しない。
- 装甲車両の生命点を0にした時点で車両は炎上し、民兵は潰走する。その時点で戦闘は終了する。
"""
new_capture = """- 鹵獲：対戦車砲装甲車両は有人車両として扱う。生命点が1のときにCore v1.01の【ネゴシエーション】に成功した場合、乗員を【捕虜】にし、車両を【鹵獲】して戦闘から除外する。火力中枢を失った残存民兵は戦意を喪失して潰走し、その時点で戦闘を終了する。通常の戦利品に加えて、車両を破壊せず確保した追加戦果として軍票+5枚を得る。ここは最終イベントであるため、Core v1.01の【車両】鹵獲によるd66一の位補正を使用する機会は発生しない。
- 装甲車両の生命点を0にした時点で車両は炎上し、民兵は潰走する。その時点で戦闘は終了する。この場合、鹵獲による軍票+5枚は得られない。
"""
if s.count(old_capture) != 1:
    raise SystemExit(f"final capture anchor count={s.count(old_capture)}")
s = s.replace(old_capture, new_capture, 1)

ep_anchor = """### 3周目

_大通りを通り抜ける。_
"""
ep_new = """### 3周目

#### 対戦車砲装甲車両を鹵獲した場合

_敵の火力中枢だった装甲車両は、破壊されることなくこちらの手に落ちた。_
  _武装を解除された乗員を確保し、車両の位置と状態を後続部隊へ送信する。_
  _後に回収された車両と対戦車砲は、敵の装備と戦術を知るための貴重な戦果となった。_

_大通りを通り抜ける。_
"""
if s.count(ep_anchor) != 1:
    raise SystemExit(f"epilogue anchor count={s.count(ep_anchor)}")
s = s.replace(ep_anchor, ep_new, 1)
scenario.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")

old52 = """- 3周目最終イベントの【対戦車砲装甲車両】も有人車両として鹵獲可能とする。ただし最終イベント中のため、鹵獲後にd66を振る機会はなく、車両の標準進路補正は実質的に発生しない。
- 3周目最終イベントで車両を鹵獲した場合は「生命点0による撃破」ではないため、民兵の潰走条件は発生せず、残存民兵との戦闘を継続する。
"""
new52 = """- 3周目最終イベントの【対戦車砲装甲車両】も有人車両として鹵獲可能とする。ただし最終イベント中のため、鹵獲後にd66を振る機会はなく、車両の標準進路補正は実質的に発生しない。
- 3周目最終イベントにおける鹵獲成功後の処理は、後続の第53項で追加報酬と民兵潰走を含む最終仕様へ更新する。
"""
if a.count(old52) != 1:
    raise SystemExit(f"audit52 anchor count={a.count(old52)}")
a = a.replace(old52, new52, 1)

heading = "## 53. Black Sun 3周目最終戦の鹵獲報酬 — 採用済み"
section = """

## 53. Black Sun 3周目最終戦の鹵獲報酬 — 採用済み

ユーザー承認により、最終イベントでは通常の車両鹵獲効果である「次の固定イベントまでd66一の位±1」を利用する機会がないため、対戦車砲装甲車両を破壊せず確保したこと自体を追加戦果として報酬化する。

- 対戦車砲装甲車両の生命点を1で止め、【ネゴシエーション】に成功した場合、乗員を【捕虜】、車両を【鹵獲】とする。
- 車両を鹵獲すると火力中枢を失った残存民兵は戦意を喪失して潰走し、その時点で戦闘を終了する。
- 鹵獲成功時は通常の戦利品に加えて軍票+5枚を得る。
- 生命点0まで攻撃して車両を撃破した場合も従来どおり民兵は潰走して戦闘終了となるが、鹵獲による軍票+5枚は得られない。
- 鹵獲成功時だけ表示する3周目専用エピローグを追加し、乗員確保、車両位置の後続部隊への送信、後日の車両・対戦車砲回収を描写する。
- 追加経験点は設定しない。作戦完了時の成長速度はCore v1.01の既定を維持する。

これにより、撃破は「HP0まで削れば確実に戦闘終了」、鹵獲は「HP1で攻撃を止め、指揮点を消費して交渉判定に成功すれば、同じ戦闘終了に加えて軍票5枚を得る」という別のリスク／報酬経路になる。最終イベントでも【鹵獲】を選ぶ実利と物語上の達成感を確保する。
"""
if heading not in a:
    a = a.rstrip() + section + "\n"
audit.write_text(a, encoding="utf-8")
